document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".header__theme");if(e){const t=document.documentElement;e.addEventListener("click",()=>{const e="dark"===t.dataset.theme?"light":"dark";t.dataset.theme=e,localStorage.setItem("theme",e)})}const t=document.querySelector(".header__language");t&&t.addEventListener("click",function(){t.classList.toggle("open")});const n=document.querySelector(".header__languages");n&&n.addEventListener("click",function(e){e.stopPropagation(),e.target.classList.contains("header__languages")&&t.classList.remove("open")});const c=document.querySelector(".header__burger-btn"),o=document.querySelector(".header__burger");c&&o&&c.addEventListener("click",function(){o.classList.toggle("open")})});